=head2 Google::Cloud::Redis::Cluster::V1beta1::CloudRedisCluster::RescheduleClusterMaintenanceRequest

Request for rescheduling a cluster maintenance.

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->name() >> / C<< $msg->name($value) >>

Type: C<String>

Required. Redis Cluster instance resource name using the form:
    `projects/{project_id}/locations/{location_id}/clusters/{cluster_id}`
where `location_id` refers to a GCP region.

=item * C<< $msg->reschedule_type() >> / C<< $msg->reschedule_type($value) >>

Type: C<Enum> (L<Google::Cloud::Redis::Cluster::V1beta1::RescheduleClusterMaintenanceRequest::RescheduleType>)

Required. If reschedule type is SPECIFIC_TIME, must set up schedule_time as
well.

=item * C<< $msg->schedule_time() >> / C<< $msg->schedule_time($value) >>

Type: C<Message> (L<Google::Protobuf::Timestamp::Timestamp>)

Optional. Timestamp when the maintenance shall be rescheduled to if
reschedule_type=SPECIFIC_TIME, in RFC 3339 format, for
example `2012-11-15T16:19:00.094Z`.

=back

=head3 Enum: RescheduleClusterMaintenanceRequest::RescheduleType

=over 4

=item * C<RESCHEDULE_TYPE_UNSPECIFIED> => C<0>

=item * C<IMMEDIATE> => C<1>

=item * C<SPECIFIC_TIME> => C<3>

=back

=head2 Google::Cloud::Redis::Cluster::V1beta1::CloudRedisCluster::EncryptionInfo

EncryptionInfo describes the encryption information of a cluster or a backup.

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->encryption_type() >> / C<< $msg->encryption_type($value) >>

Type: C<Enum> (L<Google::Cloud::Redis::Cluster::V1beta1::EncryptionInfo::Type>)

Output only. Type of encryption.

=item * C<< $msg->kms_key_versions() >> / C<< $msg->kms_key_versions($value) >>

Type: C<String>

Output only. KMS key versions that are being used to protect the data
at-rest.

=item * C<< $msg->kms_key_primary_state() >> / C<< $msg->kms_key_primary_state($value) >>

Type: C<Enum> (L<Google::Cloud::Redis::Cluster::V1beta1::EncryptionInfo::KmsKeyState>)

Output only. The state of the primary version of the KMS key perceived by
the system. This field is not populated in backups.

=item * C<< $msg->last_update_time() >> / C<< $msg->last_update_time($value) >>

Type: C<Message> (L<Google::Protobuf::Timestamp::Timestamp>)

Output only. The most recent time when the encryption info was updated.

=back

=head3 Enum: EncryptionInfo::Type

=over 4

=item * C<TYPE_UNSPECIFIED> => C<0>

=item * C<GOOGLE_DEFAULT_ENCRYPTION> => C<1>

=item * C<CUSTOMER_MANAGED_ENCRYPTION> => C<2>

=back

=head3 Enum: EncryptionInfo::KmsKeyState

=over 4

=item * C<KMS_KEY_STATE_UNSPECIFIED> => C<0>

=item * C<ENABLED> => C<1>

=item * C<PERMISSION_DENIED> => C<2>

=item * C<DISABLED> => C<3>

=item * C<DESTROYED> => C<4>

=item * C<DESTROY_SCHEDULED> => C<5>

=item * C<EKM_KEY_UNREACHABLE_DETECTED> => C<6>

